insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (77, 4, 131, 147, 'سورة النساء ١٣١ – ١٤٧', 'كونوا قوّامين بالقسط، وصفات المنافقين، و«ما يفعل الله بعذابكم إن شكرتم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 77) = $j$[{"lbl": "الآيات ١٣١ – ١٣٤", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا ﴿١٣١﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿١٣٢﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا ﴿١٣٣﴾ مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا ﴿١٣٤﴾", "w": [["وله ما في السموات وما في الأرض", "خلقاً وملكاً وتصرّفاً وتدبيراً."], ["وصّينا", "عهدنا إليهم بالتقوى."], ["أوتوا الكتاب", "اليهود والنصارى."], ["وكيلاً", "الوكيل: من يُفوَّض إليه الأمر كله ويقوم بتدبيره على أحسن الوجوه."], ["ثواب الدنيا", "جزاء العمل فيها."], ["ثواب الآخرة", "جزاء العمل فيها، وهو الجنة."], ["سميعاً بصيراً", "سميعاً لأقوال العباد، بصيراً بأعمالهم، وسيجزيهم بها."]], "m": "لما وعد الله الزوجين المتفرّقين بالإغناء، ذكر أنه يملك ما في السموات وما في الأرض، فهو قادر على إغنائهما. ثم خاطب الأمة جمعاء: ولقد وصّينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله، فلا تُقدموا على مخالفته ولا تخرجوا عن طاعته، وإن تكفروا فإن ذلك لا يضرّه شيئاً، فله ما في السموات وما في الأرض، وهو الغني الحميد، وكفى بالله وكيلاً. ثم أخبر أنه قادر على إذهاب الناس كلهم والإتيان بآخرين. ثم رغّب عباده فيما عنده: من كان يريد بعمله ثواب الدنيا فعند الله ثواب الدنيا والآخرة، فلِمَ يقصر العبد عمله على ثواب الدنيا وهو يعلم أن ثواب الآخرة عند الله أيضاً؟ فليطلب الثوابين معاً بالإيمان والتقوى والإحسان، وكان الله سميعاً بصيراً، فلا يُخاف معه ضياع الأعمال.", "h": ["الوصية بالتقوى، وذلك بترك الشرك والمعاصي بعد الإيمان وعمل الصالحات.", "غنى الله تعالى عن سائر خلقه.", "قدرة الله تعالى على إذهاب الناس كلهم والإتيان بغيرهم.", "وجوب الإخلاص في العمل لله تعالى، وحرمة طلب الدنيا بعمل الآخرة."], "k": "«فعند الله ثواب الدنيا والآخرة»… لماذا أطلب بعملي الأقلّ، والله يعطي الاثنين؟"}, {"lbl": "الآيات ١٣٥ – ١٣٧", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٣٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١٣٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا ﴿١٣٧﴾", "w": [["قوّامين", "جمع قوّام، وهو كثير القيام بالعدل."], ["بالقسط", "بالعدل، وهو الاستقامة والتسوية بين الخصوم."], ["تلووا", "تُحرّفوا الشهادة بألسنتكم."], ["أو تُعرضوا", "تتركوا أداءها أو بعض كلماتها."]], "m": "ينادي الله المؤمنين: كونوا قوّامين بالعدل، شهداء لله، إذ بشهادتكم ينتقل الحق من شخص إلى آخر، وقد أقامكم الله شهداء له في الأرض تؤدّى بواسطتكم الحقوق إلى أهلها، فأقيموا الشهادة لله ولو على أنفسكم أو الوالدين والأقربين، غنياً كان المشهود عليه أو فقيراً، فلا يحملنّكم غنى الغني ولا فقر الفقير على تحريف الشهادة أو كتمانها، فالله أولى بهما، فلا تتّبعوا الهوى أن تعدلوا، وإن تلووا ألسنتكم بالشهادة تحريفاً، أو تُعرضوا عنها فتتركوها، فإن الله كان بما تعملون خبيراً. وهي أعظم آية في هذا الباب. ثم دعا المؤمنين إلى تقوية إيمانهم ليبلغوا اليقين، ودعا أهل الكتاب إلى الإيمان الصحيح: آمنوا بالله ورسوله محمد ﷺ، والقرآن الذي نزّل على رسوله، والكتاب الذي أنزل من قبل، ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضلّ ضلالاً بعيداً. ثم قرّر: إن الذين آمنوا ثم كفروا، ثم آمنوا ثم كفروا، ثم ازدادوا كفراً، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً.", "h": ["وجوب العدل في القضاء والشهادة.", "حرمة شهادة الزور، وحرمة التخلّي عن الشهادة لمن تعيّنت عليه.", "وجوب الاستمرار على الإيمان وتقويته حتى الموت عليه.", "بيان أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر.", "المرتد يُستتاب ثلاثة أيام وإلا قُتل كفراً، أخذاً من قوله: «ثم آمنوا ثم كفروا»."], "k": "«ولو على أنفسكم أو الوالدين والأقربين»… هل أقول الحق حين يكون ضدّي أو ضدّ من أحب؟"}, {"lbl": "الآيات ١٣٨ – ١٤١", "q": "بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا ﴿١٣٨﴾ ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا ﴿١٣٩﴾ وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا ﴿١٤٠﴾ ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا ﴿١٤١﴾", "w": [["بشّر المنافقين", "البشارة: الخبر الذي تتأثر به بشرة من يُلقى إليه، خيراً كان أو شراً."], ["أولياء", "يوالونهم محبةً ونصرةً لهم على المؤمنين."], ["العزّة", "الغلبة والمنعة."], ["يُستهزأ بها", "يذكرونها استخفافاً بها وإنكاراً لها."], ["يخوضوا", "يتكلموا في موضوع آخر."], ["مثلهم", "في الكفر والإثم."], ["يتربّصون بكم", "ينتظرون متى يحصل لكم انهزام فيعلنون كفرهم."], ["نصيب", "من النصر، وعبّر عنه بالنصيب القليل لأن انتصارهم على المؤمنين قليل."], ["نستحوذ عليكم", "نستولِ عليكم ونمنعكم من المؤمنين إن قاتلوكم."], ["سبيلاً", "طريقاً إلى إذلالهم واستعبادهم والتسلّط عليهم."]], "m": "أمر الله رسوله ﷺ أن يخبر المنافقين، بلفظ البشارة تهكّماً، بأن لهم عذاباً أليماً، ثم وصفهم بأخسّ صفاتهم: الذين يتخذون الكافرين أولياء من دون المؤمنين، يعطونهم محبتهم ونصرتهم، أيبتغون عندهم العزة؟ فإن العزة لله جميعاً، فمن أعزّه الله عزّ، ومن أذلّه ذلّ، وتُطلب العزة بالإيمان وصالح الأعمال. ثم ذكّر المؤمنين بما أنزل عليهم في سورة الأنعام بمكة من النهي عن مجالسة أهل الباطل إذا خاضوا في الطعن في آيات الله، فلما أصبح للمنافقين في المدينة مجالس يخوضون فيها في آيات الله استهزاءً قال: إذا سمعتم آيات الله يُكفر بها ويُستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره، إنكم إذاً مثلهم في الإثم والجزاء، إن الله جامع المنافقين والكافرين في جهنم جميعاً. ثم وصفهم: الذين يتربّصون بكم الدوائر، فإن كان لكم فتح من الله قالوا: ألم نكن معكم؟ فأشركونا في الغنيمة، وإن كان للكافرين نصيب قالوا: ألم نستولِ عليكم ونمنعكم من المؤمنين؟ فأعطونا، يمسكون العصا من الوسط. فالله يحكم بينهم يوم القيامة، ولن يجعل الله للكافرين على المؤمنين سبيلاً لاستئصالهم أو إذلالهم ما داموا مؤمنين صادقين.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "الباعث على اتخاذ الكافرين أولياء هو الرغبة في العزة، وهذا باطل، فالعزة لله ولا تُطلب إلا منه بالإيمان واتباع منهجه.", "حرمة مجالسة أهل الباطل إذا كانوا يخوضون في آيات الله نقداً واستهزاءً وسخرية.", "الرضا بالكفر كفر، والرضا بالإثم إثم.", "تكفّل الله تعالى بعزة المؤمنين الصادقين ومنعتهم، فلا يسلّط عليهم أعداءه فيستأصلونهم أو يذلّونهم."], "k": "«فلا تقعدوا معهم حتى يخوضوا في حديث غيره»… هل أقوم من مجلس يُستهزأ فيه بالدين، ولو كان مجلساً على الإنترنت؟"}, {"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا ﴿١٤٢﴾ مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿١٤٣﴾", "w": [["يخادعون الله", "بإظهارهم ما يحب من الإيمان والطاعات، وإخفائهم الكفر."], ["وهو خادعهم", "بالستر عليهم وعدم فضيحتهم وعدم إنزال العقوبة بهم عاجلاً."], ["يراؤون", "يُظهرون الطاعات للمؤمنين كأنهم مؤمنون وما هم بمؤمنين."], ["مذبذبين", "يتردّدون بين المؤمنين والكافرين، فأي جانب عزّ كانوا معه."]], "m": "أخبر الله أن المنافقين يخادعونه بإظهار الإيمان به وبرسوله وهم غير مؤمنين، إذ الخداع أن تُري من تخادعه ما يحبه منك وتستر عنه ما يكرهه، والله عاملهم بالمثل: أراهم ما يحبون، وستر عنهم ما يكرهون، وهو العذاب المعدّ لهم عاجلاً أو آجلاً. وإذا قاموا إلى الصلاة قاموا كسالى متباطئين، لأنهم لا يؤمنون بالثواب الأخروي، يراؤون المؤمنين بالأعمال الصالحة حتى لا يتهموهم بالكفر، ولا يذكرون الله إلا قليلاً في الصلاة وخارجها، لعدم إيمانهم به وعدم حبهم له. وهم مذبذبون بين الكفر والإيمان، لا إلى المؤمنين يسكنون، ولا إلى الكافرين، فهم في تردّد وحسرة دائمة، وهذه حال من يضلّه الله، ومن يضلل الله فلن تجد له سبيلاً.", "h": ["بيان صفات المنافقين.", "قبح الرياء وذمّ المرائين.", "ذم ترك الذكر والتقليل منه، لأمر الله تعالى بالإكثار منه في قوله: «يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً».", "ذم الحيرة والتردّد في الأمور كلها."], "k": "«وإذا قاموا إلى الصلاة قاموا كسالى»… كيف أقوم إلى صلاتي القادمة؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا ﴿١٤٤﴾ إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا ﴿١٤٥﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا ﴿١٤٦﴾ مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا ﴿١٤٧﴾", "w": [["سلطاناً مبيناً", "حجة واضحة لتعذيبكم."], ["الدرك الأسفل", "الدرك كالطابق، والدركة كالدرجة."], ["وأصلحوا", "ما كانوا قد أفسدوه من العقائد والأعمال."], ["واعتصموا بالله", "تمسّكوا بدينه وتوكّلوا عليه."], ["وأخلصوا دينهم لله", "تخلّوا عن النفاق والشرك."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يعزّهم ويكمّلهم، فنهاهم عن اتخاذ الكافرين أولياء من دون المؤمنين، بموادّتهم ومناصرتهم والثقة بهم والركون إليهم، وهدّدهم: أتريدون أن تجعلوا لله عليكم حجة واضحة، فيتخلّى عنكم ويسلّط عليكم أعداءه؟ ثم حذّرهم من النفاق أن يتسرّب إلى قلوبهم: إن المنافقين في الدرك الأسفل من النار، ولن تجد لهم نصيراً. ثم فتح باب التوبة رحمةً بعباده: إلا الذين تابوا فآمنوا حق الإيمان، وأصلحوا أعمالهم، واعتصموا بالله ونفضوا أيديهم من الكافرين، وأخلصوا دينهم لله فلم يراؤوا أحداً، فأولئك مع المؤمنين، وسوف يؤتي الله المؤمنين أجراً عظيماً. ثم قرّر غناه عن تعذيب خلقه: ما يفعل الله بعذابكم إن شكرتم وآمنتم؟ فالعبد مهما جنى وأساء إذا تاب وأصلح فآمن وشكر لا يعذّبه، وكان الله شاكراً لا يضيع المعروف عنده، عليماً.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "إذا عصى المؤمنون ربهم فاتخذوا الكافرين أولياء سلّط الله عليهم أعداءهم فساموهم الخسف.", "التوبة تجُبّ ما قبلها، حتى إن التائب من ذنبه كمن لا ذنب له، مهما كان الذنب الذي غشيه.", "لا يعذّب الله تعالى المؤمن الشاكر لا في الدنيا ولا في الآخرة، فالإيمان والشكر أمان الإنسان."], "k": "«ما يفعل الله بعذابكم إن شكرتم وآمنتم»… على أي نعمة أشكر الله الآن بقلبي ولساني وعملي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 77;
insert into public.tdb_cards(topic, i, body) select 77, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣١ – ١٣٤", "q": "وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا ﴿١٣١﴾ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿١٣٢﴾ إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا ﴿١٣٣﴾ مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا ﴿١٣٤﴾", "w": [["وله ما في السموات وما في الأرض", "خلقاً وملكاً وتصرّفاً وتدبيراً."], ["وصّينا", "عهدنا إليهم بالتقوى."], ["أوتوا الكتاب", "اليهود والنصارى."], ["وكيلاً", "الوكيل: من يُفوَّض إليه الأمر كله ويقوم بتدبيره على أحسن الوجوه."], ["ثواب الدنيا", "جزاء العمل فيها."], ["ثواب الآخرة", "جزاء العمل فيها، وهو الجنة."], ["سميعاً بصيراً", "سميعاً لأقوال العباد، بصيراً بأعمالهم، وسيجزيهم بها."]], "m": "لما وعد الله الزوجين المتفرّقين بالإغناء، ذكر أنه يملك ما في السموات وما في الأرض، فهو قادر على إغنائهما. ثم خاطب الأمة جمعاء: ولقد وصّينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله، فلا تُقدموا على مخالفته ولا تخرجوا عن طاعته، وإن تكفروا فإن ذلك لا يضرّه شيئاً، فله ما في السموات وما في الأرض، وهو الغني الحميد، وكفى بالله وكيلاً. ثم أخبر أنه قادر على إذهاب الناس كلهم والإتيان بآخرين. ثم رغّب عباده فيما عنده: من كان يريد بعمله ثواب الدنيا فعند الله ثواب الدنيا والآخرة، فلِمَ يقصر العبد عمله على ثواب الدنيا وهو يعلم أن ثواب الآخرة عند الله أيضاً؟ فليطلب الثوابين معاً بالإيمان والتقوى والإحسان، وكان الله سميعاً بصيراً، فلا يُخاف معه ضياع الأعمال.", "h": ["الوصية بالتقوى، وذلك بترك الشرك والمعاصي بعد الإيمان وعمل الصالحات.", "غنى الله تعالى عن سائر خلقه.", "قدرة الله تعالى على إذهاب الناس كلهم والإتيان بغيرهم.", "وجوب الإخلاص في العمل لله تعالى، وحرمة طلب الدنيا بعمل الآخرة."], "k": "«فعند الله ثواب الدنيا والآخرة»… لماذا أطلب بعملي الأقلّ، والله يعطي الاثنين؟"}, {"lbl": "الآيات ١٣٥ – ١٣٧", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا ﴿١٣٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا ﴿١٣٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا ﴿١٣٧﴾", "w": [["قوّامين", "جمع قوّام، وهو كثير القيام بالعدل."], ["بالقسط", "بالعدل، وهو الاستقامة والتسوية بين الخصوم."], ["تلووا", "تُحرّفوا الشهادة بألسنتكم."], ["أو تُعرضوا", "تتركوا أداءها أو بعض كلماتها."]], "m": "ينادي الله المؤمنين: كونوا قوّامين بالعدل، شهداء لله، إذ بشهادتكم ينتقل الحق من شخص إلى آخر، وقد أقامكم الله شهداء له في الأرض تؤدّى بواسطتكم الحقوق إلى أهلها، فأقيموا الشهادة لله ولو على أنفسكم أو الوالدين والأقربين، غنياً كان المشهود عليه أو فقيراً، فلا يحملنّكم غنى الغني ولا فقر الفقير على تحريف الشهادة أو كتمانها، فالله أولى بهما، فلا تتّبعوا الهوى أن تعدلوا، وإن تلووا ألسنتكم بالشهادة تحريفاً، أو تُعرضوا عنها فتتركوها، فإن الله كان بما تعملون خبيراً. وهي أعظم آية في هذا الباب. ثم دعا المؤمنين إلى تقوية إيمانهم ليبلغوا اليقين، ودعا أهل الكتاب إلى الإيمان الصحيح: آمنوا بالله ورسوله محمد ﷺ، والقرآن الذي نزّل على رسوله، والكتاب الذي أنزل من قبل، ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضلّ ضلالاً بعيداً. ثم قرّر: إن الذين آمنوا ثم كفروا، ثم آمنوا ثم كفروا، ثم ازدادوا كفراً، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً.", "h": ["وجوب العدل في القضاء والشهادة.", "حرمة شهادة الزور، وحرمة التخلّي عن الشهادة لمن تعيّنت عليه.", "وجوب الاستمرار على الإيمان وتقويته حتى الموت عليه.", "بيان أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر.", "المرتد يُستتاب ثلاثة أيام وإلا قُتل كفراً، أخذاً من قوله: «ثم آمنوا ثم كفروا»."], "k": "«ولو على أنفسكم أو الوالدين والأقربين»… هل أقول الحق حين يكون ضدّي أو ضدّ من أحب؟"}, {"lbl": "الآيات ١٣٨ – ١٤١", "q": "بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا ﴿١٣٨﴾ ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا ﴿١٣٩﴾ وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا ﴿١٤٠﴾ ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا ﴿١٤١﴾", "w": [["بشّر المنافقين", "البشارة: الخبر الذي تتأثر به بشرة من يُلقى إليه، خيراً كان أو شراً."], ["أولياء", "يوالونهم محبةً ونصرةً لهم على المؤمنين."], ["العزّة", "الغلبة والمنعة."], ["يُستهزأ بها", "يذكرونها استخفافاً بها وإنكاراً لها."], ["يخوضوا", "يتكلموا في موضوع آخر."], ["مثلهم", "في الكفر والإثم."], ["يتربّصون بكم", "ينتظرون متى يحصل لكم انهزام فيعلنون كفرهم."], ["نصيب", "من النصر، وعبّر عنه بالنصيب القليل لأن انتصارهم على المؤمنين قليل."], ["نستحوذ عليكم", "نستولِ عليكم ونمنعكم من المؤمنين إن قاتلوكم."], ["سبيلاً", "طريقاً إلى إذلالهم واستعبادهم والتسلّط عليهم."]], "m": "أمر الله رسوله ﷺ أن يخبر المنافقين، بلفظ البشارة تهكّماً، بأن لهم عذاباً أليماً، ثم وصفهم بأخسّ صفاتهم: الذين يتخذون الكافرين أولياء من دون المؤمنين، يعطونهم محبتهم ونصرتهم، أيبتغون عندهم العزة؟ فإن العزة لله جميعاً، فمن أعزّه الله عزّ، ومن أذلّه ذلّ، وتُطلب العزة بالإيمان وصالح الأعمال. ثم ذكّر المؤمنين بما أنزل عليهم في سورة الأنعام بمكة من النهي عن مجالسة أهل الباطل إذا خاضوا في الطعن في آيات الله، فلما أصبح للمنافقين في المدينة مجالس يخوضون فيها في آيات الله استهزاءً قال: إذا سمعتم آيات الله يُكفر بها ويُستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره، إنكم إذاً مثلهم في الإثم والجزاء، إن الله جامع المنافقين والكافرين في جهنم جميعاً. ثم وصفهم: الذين يتربّصون بكم الدوائر، فإن كان لكم فتح من الله قالوا: ألم نكن معكم؟ فأشركونا في الغنيمة، وإن كان للكافرين نصيب قالوا: ألم نستولِ عليكم ونمنعكم من المؤمنين؟ فأعطونا، يمسكون العصا من الوسط. فالله يحكم بينهم يوم القيامة، ولن يجعل الله للكافرين على المؤمنين سبيلاً لاستئصالهم أو إذلالهم ما داموا مؤمنين صادقين.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "الباعث على اتخاذ الكافرين أولياء هو الرغبة في العزة، وهذا باطل، فالعزة لله ولا تُطلب إلا منه بالإيمان واتباع منهجه.", "حرمة مجالسة أهل الباطل إذا كانوا يخوضون في آيات الله نقداً واستهزاءً وسخرية.", "الرضا بالكفر كفر، والرضا بالإثم إثم.", "تكفّل الله تعالى بعزة المؤمنين الصادقين ومنعتهم، فلا يسلّط عليهم أعداءه فيستأصلونهم أو يذلّونهم."], "k": "«فلا تقعدوا معهم حتى يخوضوا في حديث غيره»… هل أقوم من مجلس يُستهزأ فيه بالدين، ولو كان مجلساً على الإنترنت؟"}, {"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا ﴿١٤٢﴾ مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا ﴿١٤٣﴾", "w": [["يخادعون الله", "بإظهارهم ما يحب من الإيمان والطاعات، وإخفائهم الكفر."], ["وهو خادعهم", "بالستر عليهم وعدم فضيحتهم وعدم إنزال العقوبة بهم عاجلاً."], ["يراؤون", "يُظهرون الطاعات للمؤمنين كأنهم مؤمنون وما هم بمؤمنين."], ["مذبذبين", "يتردّدون بين المؤمنين والكافرين، فأي جانب عزّ كانوا معه."]], "m": "أخبر الله أن المنافقين يخادعونه بإظهار الإيمان به وبرسوله وهم غير مؤمنين، إذ الخداع أن تُري من تخادعه ما يحبه منك وتستر عنه ما يكرهه، والله عاملهم بالمثل: أراهم ما يحبون، وستر عنهم ما يكرهون، وهو العذاب المعدّ لهم عاجلاً أو آجلاً. وإذا قاموا إلى الصلاة قاموا كسالى متباطئين، لأنهم لا يؤمنون بالثواب الأخروي، يراؤون المؤمنين بالأعمال الصالحة حتى لا يتهموهم بالكفر، ولا يذكرون الله إلا قليلاً في الصلاة وخارجها، لعدم إيمانهم به وعدم حبهم له. وهم مذبذبون بين الكفر والإيمان، لا إلى المؤمنين يسكنون، ولا إلى الكافرين، فهم في تردّد وحسرة دائمة، وهذه حال من يضلّه الله، ومن يضلل الله فلن تجد له سبيلاً.", "h": ["بيان صفات المنافقين.", "قبح الرياء وذمّ المرائين.", "ذم ترك الذكر والتقليل منه، لأمر الله تعالى بالإكثار منه في قوله: «يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً».", "ذم الحيرة والتردّد في الأمور كلها."], "k": "«وإذا قاموا إلى الصلاة قاموا كسالى»… كيف أقوم إلى صلاتي القادمة؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا ﴿١٤٤﴾ إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا ﴿١٤٥﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا ﴿١٤٦﴾ مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا ﴿١٤٧﴾", "w": [["سلطاناً مبيناً", "حجة واضحة لتعذيبكم."], ["الدرك الأسفل", "الدرك كالطابق، والدركة كالدرجة."], ["وأصلحوا", "ما كانوا قد أفسدوه من العقائد والأعمال."], ["واعتصموا بالله", "تمسّكوا بدينه وتوكّلوا عليه."], ["وأخلصوا دينهم لله", "تخلّوا عن النفاق والشرك."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يعزّهم ويكمّلهم، فنهاهم عن اتخاذ الكافرين أولياء من دون المؤمنين، بموادّتهم ومناصرتهم والثقة بهم والركون إليهم، وهدّدهم: أتريدون أن تجعلوا لله عليكم حجة واضحة، فيتخلّى عنكم ويسلّط عليكم أعداءه؟ ثم حذّرهم من النفاق أن يتسرّب إلى قلوبهم: إن المنافقين في الدرك الأسفل من النار، ولن تجد لهم نصيراً. ثم فتح باب التوبة رحمةً بعباده: إلا الذين تابوا فآمنوا حق الإيمان، وأصلحوا أعمالهم، واعتصموا بالله ونفضوا أيديهم من الكافرين، وأخلصوا دينهم لله فلم يراؤوا أحداً، فأولئك مع المؤمنين، وسوف يؤتي الله المؤمنين أجراً عظيماً. ثم قرّر غناه عن تعذيب خلقه: ما يفعل الله بعذابكم إن شكرتم وآمنتم؟ فالعبد مهما جنى وأساء إذا تاب وأصلح فآمن وشكر لا يعذّبه، وكان الله شاكراً لا يضيع المعروف عنده، عليماً.", "h": ["حرمة اتخاذ الكافرين أولياء من دون المؤمنين.", "إذا عصى المؤمنون ربهم فاتخذوا الكافرين أولياء سلّط الله عليهم أعداءهم فساموهم الخسف.", "التوبة تجُبّ ما قبلها، حتى إن التائب من ذنبه كمن لا ذنب له، مهما كان الذنب الذي غشيه.", "لا يعذّب الله تعالى المؤمن الشاكر لا في الدنيا ولا في الآخرة، فالإيمان والشكر أمان الإنسان."], "k": "«ما يفعل الله بعذابكم إن شكرتم وآمنتم»… على أي نعمة أشكر الله الآن بقلبي ولساني وعملي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;